Item.method_code:
return window.ModulesManager.using([
		'aras.innovator.core.ItemWindow/DefaultItemWindowView',
		'aras.innovator.core.ItemWindow/DefaultItemWindowCreator'
	],
	function(DefaultItemWindowView, Creator) {
		class EndpointConfigurationWindowView extends DefaultItemWindowView {
			getViewUrl() {
				return '/Modules/aras.innovator.WebServices/endpointConfigurationView';
			};
		}

		const view = new EndpointConfigurationWindowView(inDom,inArgs);
		const creator = new Creator(view);
		return creator.ShowView();
	});
